/**
 * Tops up the customer's wallet to the `topUpAmount` when the current wallet balance has dropped below
 * `topUpThreshold * topUpAmount`. The top up is charged to the customer through an invoice, the payment of
 * which is stored as credit on the customer's wallet.
 */
public async topUp({ customer }: { customer: ReadCustomerResponseData }): Promise<string | void> {
    if (!this.topUpAmount) {
        Offering.logger.warn(
            `Cannot top up customer ${this.customerId} on offering ${this.offeringName}. No top up amount is configured`,
        );
        return;
    }
    const topUpAmount = parseFloat(this.topUpAmount);
    const currentBalance = parseFloat(customer?.creditBalance ? customer.creditBalance : '0');
    const thresholdAmount = this.getTopUpThresholdAmount();
    Offering.logger.log(
        `Evaluating top up for customer ${this.customerId} on offering ${this.offeringName}. Balance: ${currentBalance}, threshold: ${thresholdAmount}, top up amount: ${topUpAmount}`,
    );
    if (currentBalance >= thresholdAmount) {
        Offering.logger.log(
            `Customer ${this.customerId} has a sufficient balance of ${currentBalance}. No top up required`,
        );
        return;
    }
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, topUpAmount - currentBalance));
    const { invoiceId } = await this.invoicesService.create({
        businessID: this.businessID,
        customer,
        customerId: this.customerId,
        items: lineItems,
        invoiceDate: new Date().toISOString(),
        currency: Offering.getCurrency({ customer, offering: this }),
        storePaymentAsCredit: true,
    });
    return invoiceId;
}

/**
 * Runs a single top up billing cycle for a customer.
 * The usage accrued since the last check is deducted from the customer's wallet, and afterwards the
 * wallet is topped up if the remaining balance dropped below the top up threshold.
 * No usage invoice is generated, the usage is paid for with the prepaid credit in the customer's wallet.
 */
public async processTopUpCycle({
    customer,
    creditService,
    startDate,
    endDate,
}: {
    customer: ReadCustomerResponseData;
    creditService?: CreditService;
    startDate?: Date;
    endDate?: Date;
}): Promise<string | void> {
    const { startTime, endTime } = Billing.billingCycleToTimeRange(ValidBillingCycles.topUp);
    const usageStartDate = startDate ? startDate : new Date(startTime);
    const usageEndDate = endDate ? endDate : new Date(endTime);
    // The wallet (credit) service can be passed in directly, set on the offering instance, or fall back to
    // the one available on the invoices service.
    let walletService = creditService ? creditService : this.creditService;
    if (!walletService) {
        walletService = this.invoicesService?.creditService;
    }
    const lineItems = new InvoiceLineItems();
    await Offering.getLineItemsForUsage({
        startDate: usageStartDate,
        endDate: usageEndDate,
        customer,
        lineItems,
        negative: false,
        businessID: this.businessID,
        customerId: this.customerId,
        customerService: this.customerService,
        offeringInstance: this,
        dimensions: this.dimensions,
    });
    const usageTotal = lineItems.getTotal();
    Offering.logger.log(
        `Top up usage for customer ${this.customerId} on offering ${
            this.offeringName
        } between ${usageStartDate.toISOString()} and ${usageEndDate.toISOString()} is ${usageTotal}`,
    );
    if (usageTotal > 0) {
        const currentBalance = parseFloat(customer?.creditBalance ? customer.creditBalance : '0');
        if (walletService) {
            // The full usage is always deducted from the wallet, even when the usage is larger than the
            // current balance of the wallet.
            await walletService.create({
                transactionAmount: (usageTotal * -1).toFixed(2),
                customerId: this.customerId,
                businessID: this.businessID,
                timestamp: new Date().toISOString(),
                metadata: {
                    reason: `Usage for ${this.offeringName}`,
                    offeringId: this.offeringId,
                },
            });
        } else {
            Offering.logger.error(
                `Cannot deduct usage from the wallet of customer ${this.customerId}. No credit service available`,
            );
        }
        // Keep the in memory balance in sync with the wallet, so the top up is evaluated against the
        // balance remaining after the usage has been deducted.
        if (customer) {
            customer.creditBalance = (currentBalance - usageTotal).toFixed(2);
        }
    }
    return this.topUp({ customer });
}

