import { Job } from 'bull';
import { OfferingTopUpChecker } from './offeringTopUpChecker.service.js';
import { CustomerService } from '../../customer/customer.service.js';
import { ContractService } from '../../contract/contract.service.js';
import { CreditService } from '../../credit/credit.service.js';
import { SchedulerEntity } from '../../scheduler/entities/scheduler.entity.js';
import { Offering } from '../../offering/entities/offeringPackage.entity.js';

describe('OfferingTopUpChecker', () => {
    const businessID = 'fakeBusinessID';
    const offeringId = 'fakeOfferingId';
    let checker: OfferingTopUpChecker;
    let customerService: CustomerService;
    let contractService: ContractService;
    let creditService: CreditService;
    let offering: Offering;

    beforeEach(() => {
        offering = {
            isTopUpOffering: jest.fn(() => true),
            processTopUpCycle: jest.fn(async () => 'fakeInvoiceId'),
        } as unknown as Offering;
        customerService = {
            findAllCustomersWithOfferingId: jest.fn(async () => ({
                message: 'Found Customers',
                data: [{ customerId: 'customerOne' }, { customerId: 'customerTwo' }],
            })),
        } as unknown as CustomerService;
        contractService = {
            findOne: jest.fn(async () => ({ offering })),
        } as unknown as ContractService;
        creditService = {} as unknown as CreditService;
        checker = new OfferingTopUpChecker(customerService, contractService, creditService);
    });

    test('runs the top up cycle for every customer enrolled in the offering', async () => {
        await checker.evaluateTopUps({
            data: { scheduleParameters: { businessID, offeringId, dimensionType: 'offeringTopUpChecker' } },
        } as Job<SchedulerEntity>);
        expect(customerService.findAllCustomersWithOfferingId).toBeCalledWith({ businessID, offeringId });
        expect(offering.processTopUpCycle).toBeCalledTimes(2);
        expect(offering.processTopUpCycle).toBeCalledWith({
            customer: { customerId: 'customerOne' },
            creditService,
        });
    });

    test('does not run the top up cycle for offerings which are not top up offerings', async () => {
        offering.isTopUpOffering = jest.fn(() => false);
        await checker.evaluateTopUps({
            data: { scheduleParameters: { businessID, offeringId, dimensionType: 'offeringTopUpChecker' } },
        } as Job<SchedulerEntity>);
        expect(offering.processTopUpCycle).not.toBeCalled();
    });
});
